package com.eillance.screentranslate.licenses

import android.content.Context
import org.json.JSONObject

/**
 * Reads the notices in assets/licenses/, generated by `./gradlew :app:updateLicenses`
 * (see gradle/licenses.gradle.kts for the component table).
 */
data class LicenseEntry(
  val name: String,
  val version: String,
  val license: String,
  val url: String,
  val file: String,
  val section: String,
  val note: String,
)

data class LicenseSection(val id: String, val title: String, val entries: List<LicenseEntry>)

data class LicenseIndex(val sourceNotice: String, val sections: List<LicenseSection>)

object OpenSourceLicenses {
  private const val DIR = "licenses"

  fun load(context: Context): LicenseIndex {
    val json = JSONObject(context.assets.open("$DIR/index.json").bufferedReader().use { it.readText() })
    val components = json.getJSONArray("components")
    val entries = (0 until components.length()).map { i ->
      val c = components.getJSONObject(i)
      LicenseEntry(
        name = c.getString("name"),
        version = c.optString("version"),
        license = c.getString("license"),
        url = c.getString("url"),
        file = c.getString("file"),
        section = c.getString("section"),
        note = c.optString("note"),
      )
    }
    val sections = json.getJSONArray("sections")
    return LicenseIndex(
      sourceNotice = json.getString("mplSourceNotice"),
      sections = (0 until sections.length()).map { i ->
        val s = sections.getJSONObject(i)
        val id = s.getString("id")
        LicenseSection(id, s.getString("title"), entries.filter { it.section == id })
      },
    )
  }

  fun text(context: Context, entry: LicenseEntry): String =
    context.assets.open("$DIR/${entry.file}").bufferedReader().use { it.readText() }
}
